uv run python - <<'PY'
import pandas as pd, numpy as np
train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(float)
idx = np.arange(len(train))
folds = np.array_split(idx, 5)

def rmse(a,b):
    return float(np.sqrt(np.mean((a-b)**2)))

def scale(Xtr, Xva):
    mu = Xtr.mean(axis=0)
    sd = Xtr.std(axis=0)
    sd[sd == 0] = 1.0
    return (Xtr-mu)/sd, (Xva-mu)/sd

def knn(Xtr,ytr,Xva,k,weighted=True,scaled=False,power=1.0):
    if scaled:
        Xtr, Xva = scale(Xtr, Xva)
    d = ((Xva[:,None,:]-Xtr[None,:,:])**2).sum(axis=2)
    nn = np.argpartition(d, kth=min(k-1, len(Xtr)-1), axis=1)[:,:k]
    ds = np.take_along_axis(d, nn, axis=1)
    ys = ytr[nn]
    if weighted:
        w = 1.0 / np.maximum(ds, 1e-12)**power
        return (w*ys).sum(axis=1)/w.sum(axis=1)
    return ys.mean(axis=1)

def local_ridge(Xtr,ytr,Xva,k,alpha=1.0,scaled=False):
    if scaled:
        Xtr2, Xva2 = scale(Xtr, Xva)
    else:
        Xtr2, Xva2 = Xtr, Xva
    d = ((Xva2[:,None,:]-Xtr2[None,:,:])**2).sum(axis=2)
    out=[]
    p = Xtr2.shape[1]
    I = np.eye(p+1); I[0,0]=0.0
    for i in range(len(Xva2)):
        nn = np.argpartition(d[i], kth=min(k-1, len(Xtr2)-1))[:k]
        Xn = Xtr2[nn]
        yn = ytr[nn]
        dn = d[i, nn]
        w = 1.0 / np.maximum(dn, 1e-12)
        X1 = np.c_[np.ones(len(Xn)), Xn]
        A = X1.T @ (w[:,None] * X1) + alpha * I
        b = X1.T @ (w * yn)
        coef = np.linalg.solve(A, b)
        out.append(np.r_[1.0, Xva2[i]] @ coef)
    return np.array(out)

configs = []
for k in [3,5,7,9,11,15]:
    for weighted in [False, True]:
        for scaled in [False, True]:
            for power in ([0.5,1.0,2.0] if weighted else [1.0]):
                configs.append((f"knn_k{k}_{'w' if weighted else 'u'}_{'scaled' if scaled else 'raw'}_p{power}", lambda Xtr,ytr,Xva,k=k,weighted=weighted,scaled=scaled,power=power: knn(Xtr,ytr,Xva,k,weighted,scaled,power)))
for k in [10,15,20,30]:
    for alpha in [1e-3,1e-2,1e-1,1,10]:
        for scaled in [False, True]:
            configs.append((f"localridge_k{k}_a{alpha}_{'scaled' if scaled else 'raw'}", lambda Xtr,ytr,Xva,k=k,alpha=alpha,scaled=scaled: local_ridge(Xtr,ytr,Xva,k,alpha,scaled)))

best=[]
for name, fn in configs:
    scores=[]
    for va in folds:
        tr = np.setdiff1d(idx, va)
        scores.append(rmse(y[va], fn(X[tr], y[tr], X[va])))
    best.append((float(np.mean(scores)), name))
for score, name in sorted(best)[:20]:
    print(round(score, 6), name)
